/* Football Career Hub Mobile — offline-first personal career journal */
(()=>{'use strict';
const $=(s,base=document)=>base.querySelector(s), $$=(s,base=document)=>Array.from(base.querySelectorAll(s));
const root=$('#app'), modalRoot=$('#modal-root'), toastEl=$('#toast');
const KEY='football-career-mobile-state-v1', DB_NAME='football-career-mobile-v1';
const uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-3);
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const safeImage=s=>(typeof s==='string'&&/^data:image\/(jpeg|jpg|png|webp|gif);base64,/i.test(s))?s:'';
const abbr=s=>(String(s||'?').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase());
const today=()=>new Date().toLocaleDateString('sv-SE');
const shortDate=d=>{if(!d)return '日付なし';let a=String(d).split('-');return a.length===3?`${a[0]}/${a[1]}/${a[2]}`:esc(d)};
const n=v=>Number(v)||0, clamp=(v,min,max)=>Math.min(max,Math.max(min,Number(v)||0));
const fmtNum=v=>new Intl.NumberFormat('ja-JP').format(v||0);
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2300)}
function base(){return {version:1,careers:[],activeId:null,updatedAt:new Date().toISOString()}}
function createCareer(game,club,season,league){return {id:uid(),game:game||'FC26',club:club||'My Club',season:season||'2026/27',league:league||'Premier League',stadium:'',manager:'',bio:'',crest:'',cover:'',players:[],matches:[],otherMatches:[],posts:[],transfers:[],tactics:{formation:'4-3-3',slots:[]},favorites:[],customScouts:[],createdAt:today()}}
let app=base(),db=null,persistMethod='indexedDB',activePage='home',subPage='',playerId=null,playerTab='profile',socialFilter='all',statsTab='table',squadFilter='ALL',scoutFilter='すべて',scoutSearch='',currentModalSave=null,matchDraft=null,drag=null,lastRendered=0,saveTimer=0;
async function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('IndexedDB unavailable'));const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('state'))req.result.createObjectStore('state')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('DB error'))})}
async function dbGet(key='main'){return new Promise((res,rej)=>{let t=db.transaction('state','readonly'),r=t.objectStore('state').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function dbPut(value,key='main'){return new Promise((res,rej)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(value,key);t.oncomplete=()=>res();t.onerror=()=>rej(t.error||Error('save failed'))})}
const cloud=window.CareerCloud||null;
const readOnly=Boolean(cloud && !cloud.isAdmin);
const localKey=cloud?'cloud-user:'+cloud.uid:'main';
async function load(){
 try{db=await openDB();let value;if(cloud){const local=await dbGet(localKey);value=readOnly?cloud.initialState:((cloud.shouldUseLocalCache&&local)?local:(cloud.initialState||local))}else value=await dbGet();if(value&&Array.isArray(value.careers))app=value;else if(!cloud){const legacy=localStorage.getItem(KEY);if(legacy)app=JSON.parse(legacy)}}
 catch(e){persistMethod='localStorage';if(cloud?.initialState)app=cloud.initialState;else if(!readOnly)try{const value=localStorage.getItem(cloud?KEY+'-'+cloud.uid:KEY);if(value)app=JSON.parse(value)}catch(_){}}
 if(!app||!Array.isArray(app.careers))app=base();
 if(!app.careers.find(c=>c.id===app.activeId))app.activeId=app.careers[0]?.id||null;
 if(cloud&&cloud.initialState&&db&&!cloud.shouldUseLocalCache)try{await dbPut(app,localKey)}catch(e){}
 render();
 if(cloud&&!readOnly&&(cloud.shouldUseLocalCache||!cloud.initialState)&&app.careers.length&&!cloud.conflict)cloud.queue(app);
 if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
function saveSoon(){if(readOnly)return;if(cloud)cloud.markPending();app.updatedAt=new Date().toISOString();if(db)dbPut(app,localKey).catch(()=>{});const el=$('#save-info');if(el)el.textContent='保存中…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveNow(),350)}
async function saveNow(pushCloud=true){if(readOnly)return false;clearTimeout(saveTimer);let localOk=false;
 try{if(db)await dbPut(app,localKey);else localStorage.setItem(cloud?KEY+'-'+cloud.uid:KEY,JSON.stringify(app));localOk=true}
 catch(e){const el=$('#save-info');if(el)el.textContent='端末保存エラー';toast('端末へ保存できませんでした。JSONバックアップをご確認ください')}
 if(cloud&&pushCloud)cloud.queue(app);
 const el=$('#save-info');if(el&&localOk)el.textContent=cloud?cloud.status:'保存済み';
 return localOk;
}
function c(){return app.careers.find(x=>x.id===app.activeId)||null}
function pic(src,cls='avatar',label=''){src=safeImage(src);return `<span class="${cls}">${src?`<img src="${src}" alt="">`:esc(abbr(label))}</span>`}
function crest(club,cls='club-badge'){return `<span class="${cls}">${safeImage(club.crest)?`<img src="${safeImage(club.crest)}" alt="">`:'FC'}</span>`}
function icons(k){return ({home:'⌂',matches:'▦',squad:'♙',stats:'♜',social:'♧',more:'•••'})[k]}
const navItems=[['home','ホーム'],['matches','試合'],['squad','選手'],['stats','成績'],['social','SNS'],['more','その他']];
function nav(){return `<nav class="bottom-nav" aria-label="画面切り替え">${navItems.map(([k,label])=>`<button class="${activePage===k?'selected':''}" data-nav="${k}"><span class="nav-ico">${icons(k)}</span><span class="nav-label">${label}</span></button>`).join('')}</nav>`}
function pageTitle(){if(playerId)return'選手プロフィール';if(activePage==='more'&&subPage)return ({club:'クラブ紹介',tactics:'戦術・フォーメーション',transfers:'移籍履歴',scout:'スカウト',settings:'データ管理'})[subPage]||'その他';return ({home:'クラブホーム',matches:'試合センター',squad:'スカッド',stats:'シーズン成績',social:'クラブSNS',more:'メニュー'})[activePage]}
function render(){lastRendered=Date.now();document.documentElement.classList.toggle('read-only',readOnly);const club=c();if(!club){root.innerHTML=welcome();return}
 let content;if(playerId){content=playerView(club)}else if(activePage==='more'&&subPage){content=({club:clubView,tactics:tacticsView,transfers:transfersView,scout:scoutView,settings:settingsView})[subPage]?.(club)||moreView(club)}else{content=({home:homeView,matches:matchesView,squad:squadView,stats:statsView,social:socialView,more:moreView})[activePage]?.(club)||homeView(club)}
 root.innerHTML=`<header class="app-top"><div class="top-title"><div class="app-kicker">${esc(club.game)} ・ ${esc(club.season)}</div><div class="app-title">${playerId?'‹ '+pageTitle():pageTitle()}</div></div><div class="top-right">${playerId||subPage?`<button class="icon-button" data-action="back" aria-label="戻る">‹</button>`:`<button class="icon-button" data-action="switch" aria-label="クラブ切り替え">⌄</button>`}${readOnly?`<button class="save-pill viewer-login" data-action="login">🔐 管理者ログイン</button>`:`<button class="save-pill" data-action="save">💾 <span id="save-info">${esc(cloud?.status||'保存済み')}</span></button>`}</div></header><main class="page">${content}</main>${nav()}`;
}
function setPage(p){activePage=p;subPage='';playerId=null;playerTab='profile';render();window.scrollTo(0,0)}
function openSub(p){activePage='more';subPage=p;playerId=null;render();window.scrollTo(0,0)}
function openPlayer(id){playerId=id;playerTab='profile';render();window.scrollTo(0,0)}
function back(){if(playerId){playerId=null;activePage='squad'}else if(subPage){subPage=''}else{activePage='home'}render();window.scrollTo(0,0)}
function welcome(){if(readOnly)return `<section class="splash" style="padding:28px 20px;min-height:78dvh"><div class="logo-big">F<span>⚽</span>C</div><strong>Football Career Hub</strong><p class="small muted">公開中のキャリアはまだありません。管理者が登録すると、ここに自動で表示されます。</p><button class="btn primary" data-action="login">🔐 管理者ログイン</button></section>`;return `<section class="splash" style="padding:28px 20px;min-height:100dvh"><div class="logo-big">F<span>⚽</span>C</div><strong style="font-size:25px">Football Career Hub</strong><span>YOUR CAREER. YOUR CLUB.</span><div class="card inset" style="width:100%;margin-top:36px;text-align:left"><h2 style="margin:0 0 8px;font-size:20px">はじめよう！ ⚽</h2><p class="muted small" style="line-height:1.9">管理者がクラブを登録すると、全端末からいつでも閲覧できます。</p><form id="welcome-form" class="form-grid"><div class="form-field"><label>ゲーム</label><select name="game"><option>FC26</option><option>FIFA17</option><option>FIFA18</option><option>FIFA19</option><option>FIFA22</option><option>FIFA23</option><option>FC24</option><option>FC25</option><option>その他</option></select></div><div class="form-field"><label>シーズン</label><input name="season" value="2026/27" required></div><div class="form-field full"><label>クラブ名</label><input name="club" placeholder="例：FC Nova Barcelona" value="FC Nova Barcelona" required></div><div class="form-field full"><label>所属リーグ</label><input name="league" value="Premier League"></div><div class="full"><button class="btn primary wide" type="submit">マイクラブを作成 →</button></div></form></div><p class="small muted" style="max-width:300px;line-height:1.8;text-align:center">最初は空の記録から始まります。作成後、選手・試合・写真を自由に登録できます。</p></section>`}
function teamTotals(club,leagueOnly=false){let ms=club.matches.filter(m=>!leagueOnly||m.leagueMatch!==false), w=0,d=0,l=0,gf=0,ga=0;ms.forEach(m=>{gf+=n(m.gf);ga+=n(m.ga);if(n(m.gf)>n(m.ga))w++;else if(n(m.gf)<n(m.ga))l++;else d++});return {p:ms.length,w,d,l,gf,ga,gd:gf-ga,pts:3*w+d}}
function playerStat(club,p){let base=p.manual||{},stats={apps:n(base.apps),starts:0,goals:n(base.goals),assists:n(base.assists),minutes:n(base.minutes)};club.matches.forEach(m=>{const perf=m.players?.find(x=>x.id===p.id);if(perf){if(perf.role==='start'||perf.role==='sub'){stats.apps++;if(perf.role==='start')stats.starts++;stats.minutes+=n(perf.minutes)}stats.goals+=n(perf.goals);stats.assists+=n(perf.assists)}});return stats}
function resultLabel(m){return n(m.gf)>n(m.ga)?'<span class="result win">勝</span>':n(m.gf)<n(m.ga)?'<span class="result lose">負</span>':'<span class="result draw">分</span>'}
function empty(icon,title,body,btn,action){return `<div class="empty"><div class="big">${icon}</div><b>${title}</b><p>${body}</p>${btn?`<button class="btn primary" data-action="${action}">${btn}</button>`:''}</div>`}
function homeView(club){let t=teamTotals(club),games=[...club.matches].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),leader=club.players.map(p=>({p,s:playerStat(club,p)})).sort((a,b)=>b.s.goals-a.s.goals)[0];return `<section class="hero">${safeImage(club.cover)?`<img class="hero-cover" src="${safeImage(club.cover)}">`:''}<div class="row between">${crest(club)}<span class="chip">${esc(club.game)}</span></div><h1>${esc(club.club)}</h1><div class="hero-sub">${esc(club.league||'所属リーグ未設定')} ・ ${esc(club.season)}</div><div style="margin-top:15px"><button class="btn tiny" data-sub="club">クラブを見る ›</button></div></section>
<div class="metrics"><div class="metric"><strong>${t.p}</strong><span>試合</span></div><div class="metric"><strong>${t.w}</strong><span>勝利</span></div><div class="metric"><strong>${t.pts}</strong><span>勝点</span></div><div class="metric"><strong>${t.gf}</strong><span>ゴール</span></div></div>
<div class="section-head"><h2>クイックメニュー</h2><small>よく使う操作</small></div><div class="quick-grid"><button class="quick-btn" data-action="addMatch">試合結果を登録 <b>＋</b></button><button class="quick-btn" data-action="addPlayer">選手を登録 <b>＋</b></button><button class="quick-btn" data-sub="tactics">スタメンを編集 <b>›</b></button><button class="quick-btn" data-action="addPost">SNSを投稿 <b>＋</b></button></div>
<div class="section-head"><h2>最近の試合</h2><button class="btn tiny" data-nav="matches">一覧へ ›</button></div>${games.length?`<div class="match-scroller">${games.map(m=>`<button class="score-card" data-match="${esc(m.id)}"><small>${esc(m.competition||'試合')} ・ ${shortDate(m.date)}</small><h4>${esc(club.club)}<br>vs ${esc(m.opponent)}</h4><span class="score-number">${n(m.gf)} - ${n(m.ga)}</span>　${resultLabel(m)}</button>`).join('')}</div>`:empty('▦','まだ試合がありません','試合を入力すると結果や選手成績が反映されます。','最初の試合を登録','addMatch')}
<div class="section-head"><h2>注目選手</h2><button class="btn tiny" data-nav="squad">スカッドへ ›</button></div>${leader?`<button class="person-row card" style="border-radius:15px" data-player="${esc(leader.p.id)}">${pic(leader.p.photo,'avatar',leader.p.name)}<span class="grow"><span class="name">#${esc(leader.p.num||'–')} ${esc(leader.p.name)}</span><span class="detail">${esc(leader.p.pos||'FW')} ・ ${leader.s.apps}試合</span></span><span class="rating">${leader.s.goals} G</span></button>`:empty('♙','スカッドは空です','選手写真を登録するとプロフィールやSNSにも表示できます。','選手を追加','addPlayer')}
<div class="section-head"><h2>クラブのタイムライン</h2><button class="btn tiny" data-nav="social">SNSへ ›</button></div>${club.posts.length?club.posts.slice(-1).map(p=>`<button class="menu-row" data-nav="social"><span>${esc(p.title||'クラブ投稿')}<span class="desc">${shortDate(p.date)}</span></span><span>›</span></button>`).join(''):empty('♡','クラブSNSを始めましょう','スタメン発表・GOAL投稿・ファンの反応を作れます。','投稿を作成','addPost')}`}
function matchesView(club){let ms=[...club.matches].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="row between"><div><h2 style="margin:0;font-size:20px">試合センター</h2><p class="small muted">試合結果と選手の出場記録</p></div><button class="btn primary" data-action="addMatch">＋ 試合</button></div>${ms.length?`<div class="list-card">${ms.map(m=>`<button class="player-match" data-match="${esc(m.id)}"><div class="row between"><span class="muted micro">${shortDate(m.date)} ・ ${esc(m.competition||'その他')}</span>${m.leagueMatch===false?'<span class="chip neutral">カップ</span>':'<span class="chip">リーグ</span>'}</div><div class="row between" style="margin:12px 0 5px"><div class="grow"><strong style="font-size:15px">${esc(m.opponent)}</strong><div class="small muted" style="margin-top:6px">${resultLabel(m)}${n(m.gf)} - ${n(m.ga)}　${m.venue==='away'?'アウェイ':'ホーム'}</div></div><div class="right-arrow">›</div></div></button>`).join('')}</div>`:empty('▦','試合はまだありません','自チームの結果・得点者・先発・途中出場を記録できます。','試合登録','addMatch')}
<div class="section-head"><h2>他チームの結果</h2><button class="btn tiny" data-action="otherMatch">＋ 登録</button></div><p class="small muted">入力した他チーム同士の結果は順位表にも反映されます。</p>${club.otherMatches.length?`<div class="list-card">${[...club.otherMatches].reverse().slice(0,12).map(m=>`<div class="match-line" style="padding:13px;border-bottom:1px solid var(--stroke)"><div class="row between"><span class="micro muted">${shortDate(m.date)}</span><button class="btn tiny danger" data-del-other="${esc(m.id)}">削除</button></div><div class="row between" style="font-size:13px;margin-top:7px"><b>${esc(m.home)}</b><strong>${n(m.hg)} - ${n(m.ag)}</strong><b>${esc(m.away)}</b></div></div>`).join('')}</div>`:empty('📊','他チームの試合は未登録です','結果を追加するとリーグ順位表が作成されます。','他チームの結果を登録','otherMatch')}`}
function squadView(club){let groups=[['GK','ゴールキーパー'],['DF','ディフェンダー'],['MF','ミッドフィルダー'],['FW','フォワード']];return `<div class="row between"><div><h2 style="margin:0;font-size:20px">選手</h2><p class="small muted">${club.players.length}名のスカッド</p></div><button class="btn primary" data-action="addPlayer">＋ 選手</button></div>${club.players.length?`<div class="segmented">${[['ALL','すべて'],...groups].map(([k,v])=>`<button data-squad-filter="${k}" class="${squadFilter===k?'selected':''}">${v}</button>`).join('')}</div>${groups.filter(([g])=>squadFilter==='ALL'||squadFilter===g).map(([g,title])=>{let ps=club.players.filter(p=>positionGroup(p.pos)===g).sort((a,b)=>n(a.num)-n(b.num));return ps.length?`<div class="list-card"><div class="list-card-title">${title}<small>年齢</small></div>${ps.map(p=>`<button class="person-row" data-player="${esc(p.id)}">${pic(p.photo,'avatar',p.name)}<span class="grow"><span class="name">${esc(p.num||'—')} ${esc(p.name)}</span><span class="detail">${esc(p.nation||'国籍未設定')} ・ ${esc(p.pos||'—')}</span></span><span class="muted small">${p.age?esc(p.age):'—'}</span><span class="right-arrow">›</span></button>`).join('')}</div>`:''}).join('')}`:empty('♙','スカッドを登録しましょう','名前・国籍・背番号・選手写真を追加できます。','選手登録','addPlayer')}`}
function positionGroup(pos){pos=String(pos||'').toUpperCase();if(pos==='GK')return'GK';if(['CB','LB','RB','LWB','RWB','SW'].includes(pos))return'DF';if(['CDM','CM','CAM','RM','LM','DM','AM'].includes(pos))return'MF';return'FW'}
function playerView(club){let p=club.players.find(x=>x.id===playerId);if(!p){playerId=null;return squadView(club)}let s=playerStat(club,p),idx=club.players.indexOf(p),prev=club.players[idx-1],next=club.players[idx+1];return `<div class="row between"><button class="btn tiny" data-action="back">‹ 一覧へ</button><button class="btn tiny" data-action="editPlayer" data-id="${esc(p.id)}">✎ 編集</button></div><div class="profile-top"><div class="row" style="gap:15px">${pic(p.photo,'avatar',p.name).replace('class="avatar"','class="avatar" style="width:94px;height:94px;font-size:28px"')}<div class="grow"><h1>${esc(p.name)}</h1><div class="profile-meta">${crest(club,'club-badge')}　${esc(club.club)}</div><div class="profile-meta">#${esc(p.num||'—')}　${esc(p.pos||'—')}　${p.ovr?`<span class="rating">OVR ${esc(p.ovr)}</span>`:''}</div></div></div></div>
<div class="row between" style="margin:18px 0;min-height:34px"><button class="btn tiny subtle" ${prev?`data-player="${esc(prev.id)}"`: 'disabled'}>‹ ${esc(prev?.name||'')}</button><button class="btn tiny subtle" ${next?`data-player="${esc(next.id)}"`:'disabled'}>${esc(next?.name||'')} ›</button></div>
<div class="tabs">${[['profile','プロフィール'],['matches','試合'],['stats','スタッツ'],['records','成績']].map(([k,v])=>`<button data-player-tab="${k}" class="${playerTab===k?'active':''}">${v}</button>`).join('')}</div>
${playerTab==='profile'?`<div class="card" style="margin-top:17px"><div class="info-grid">${info(p.height?p.height+' cm':'—','身長')}${info(p.age?p.age+' 歳':'—','年齢')}${info(p.nation||'—','国籍')}${info(p.num||'—','背番号')}${info(p.foot||'—','利き足')}${info(p.weight?p.weight+' kg':'—','体重')}</div></div>
<div class="card inset" style="margin-top:12px"><div class="row between"><strong>シーズン ${esc(club.season)}</strong><span class="chip">${esc(club.game)}</span></div><div class="summary-grid" style="margin-top:18px"><div><b>${s.apps}</b><span>試合</span></div><div><b>${s.goals}</b><span>ゴール</span></div><div><b>${s.assists}</b><span>アシスト</span></div><div><b>${fmtNum(s.minutes)}</b><span>出場時間</span></div></div></div>
<div class="section-head"><h2>ポジション</h2><button class="btn tiny" data-action="editPlayer" data-id="${esc(p.id)}">編集</button></div><div class="card inset"><div class="row" style="align-items:flex-start"><div class="grow"><span class="chip">● 主要ポジション</span><p style="margin-top:13px;font-size:15px;font-weight:750">${esc(posLabel(p.pos))}</p></div><div style="width:45%"><div class="mini-pitch"><span class="pos-bubble">${esc(p.pos||'ST')}</span></div></div></div></div>
<div class="section-head"><h2>選手紹介</h2><button class="btn tiny" data-action="editPlayer" data-id="${esc(p.id)}">編集</button></div><div class="card inset"><p style="white-space:pre-wrap;font-size:13px;line-height:2;margin:0">${esc(p.bio||'まだ紹介文がありません。選手の特徴やシーズンへの期待を書いてみましょう。')}</p></div>`:
playerTab==='matches'?playerMatchesView(club,p):playerTab==='stats'?playerStatsView(club,p,s):playerRecordsView(club,p,s)}
`}
function info(v,label){return `<div class="info"><b>${esc(v)}</b><span>${label}</span></div>`}
function posLabel(p){return ({GK:'ゴールキーパー',RB:'右サイドバック',LB:'左サイドバック',CB:'センターバック',CDM:'守備的ミッドフィルダー',CM:'セントラルミッドフィルダー',CAM:'攻撃的ミッドフィルダー',RW:'右ウイング',LW:'左ウイング',ST:'ストライカー',CF:'センターフォワード',RM:'右ミッドフィルダー',LM:'左ミッドフィルダー'})[p]||p||'未設定'}
function playerMatchesView(club,p){let ms=club.matches.filter(m=>m.players?.some(x=>x.id===p.id)).sort((a,b)=>b.date.localeCompare(a.date));return ms.length?`<div class="list-card">${ms.map(m=>{let perf=m.players.find(x=>x.id===p.id);return `<button class="player-match" data-match="${esc(m.id)}"><div class="row between"><span class="micro muted">${shortDate(m.date)}</span><span class="chip">${esc(m.competition||'試合')}</span></div><div class="row between" style="margin-top:12px"><div class="grow"><b>${esc(m.opponent)}</b><div style="margin-top:7px">${resultLabel(m)}<span class="small">${n(m.gf)} - ${n(m.ga)}　${m.venue==='away'?'アウェイ':'ホーム'}</span></div></div><span class="chip neutral">${perf.role==='bench'?'ベンチ':perf.role==='start'?'先発':'途中出場'}</span><span class="chip">${n(perf.minutes)}′</span><span class="right-arrow">›</span></div>${n(perf.goals)||n(perf.assists)?`<div class="micro muted" style="margin-top:8px">⚽ ${n(perf.goals)}　🎯 ${n(perf.assists)}</div>`:''}</button>`}).join('')}</div>`:empty('▦','出場記録はありません','試合入力時に先発・途中出場・ベンチを設定すると、ここに表示されます。','試合を登録','addMatch')}
function playerStatsView(club,p,s){let mp=s.apps?Math.round(s.minutes/s.apps):0, matches=club.matches.filter(m=>m.players?.some(q=>q.id===p.id)), comp={};matches.forEach(m=>{let a=comp[m.competition||'その他']??={apps:0,goals:0,assists:0};let q=m.players.find(q=>q.id===p.id);if(q.role!=='bench')a.apps++;a.goals+=n(q.goals);a.assists+=n(q.assists)});return `<div class="card inset" style="margin-top:16px"><h3 style="margin:0 0 16px">シーズンスタッツ</h3><div class="summary-grid"><div><b>${s.apps}</b><span>出場</span></div><div><b>${s.starts}</b><span>先発</span></div><div><b>${s.goals}</b><span>得点</span></div><div><b>${s.assists}</b><span>アシスト</span></div></div><hr class="line"><div class="summary-grid"><div><b>${fmtNum(s.minutes)}</b><span>出場分</span></div><div><b>${mp}</b><span>平均出場分</span></div><div><b>${s.apps?(s.goals/s.apps).toFixed(2):'0.00'}</b><span>得点/試合</span></div><div><b>${s.apps?(s.assists/s.apps).toFixed(2):'0.00'}</b><span>アシスト/試合</span></div></div></div><div class="section-head"><h2>大会別成績</h2></div>${Object.keys(comp).length?`<div class="list-card">${Object.entries(comp).map(([name,z])=>`<div class="person-row"><div class="grow"><strong>${esc(name)}</strong></div><span class="small">${z.apps}試合　${z.goals}G　${z.assists}A</span></div>`).join('')}</div>`:empty('📊','まだ大会別成績がありません','試合の出場選手を登録すると集計されます。')}`}
function playerRecordsView(club,p,s){return `<div class="card inset" style="margin-top:16px"><div class="row between"><strong>${esc(club.season)} ・ ${esc(club.game)}</strong><span class="chip">${esc(club.club)}</span></div><hr class="line"><div class="summary-grid"><div><b>${s.apps}</b><span>出場</span></div><div><b>${s.goals}</b><span>得点</span></div><div><b>${s.assists}</b><span>アシスト</span></div><div><b>${fmtNum(s.minutes)}</b><span>分</span></div></div></div><p class="small muted" style="line-height:1.8">このキャリアのシーズン記録です。別のシーズンを新しいキャリアとして登録すると独立した成績を保存できます。</p>`}
function tableRows(club){let map=new Map();function ensure(name){if(!map.has(name))map.set(name,{name,p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0});return map.get(name)}function game(home,away,hg,ag){if(!home||!away||home.trim().toLowerCase()===away.trim().toLowerCase())return;let h=ensure(home),a=ensure(away);h.p++;a.p++;h.gf+=hg;h.ga+=ag;a.gf+=ag;a.ga+=hg;if(hg>ag){h.w++;a.l++;h.pts+=3}else if(hg<ag){a.w++;h.l++;a.pts+=3}else{h.d++;a.d++;h.pts++;a.pts++}}club.matches.filter(m=>m.leagueMatch!==false).forEach(m=>{if(m.venue==='away')game(m.opponent,club.club,n(m.ga),n(m.gf));else game(club.club,m.opponent,n(m.gf),n(m.ga))});club.otherMatches.forEach(m=>game(m.home,m.away,n(m.hg),n(m.ag)));return [...map.values()].map(x=>({...x,gd:x.gf-x.ga})).sort((a,b)=>b.pts-a.pts||b.gd-a.gd||b.gf-a.gf||a.name.localeCompare(b.name))}
function statsView(club){let t=teamTotals(club),ranked=club.players.map(p=>({p,s:playerStat(club,p)})).sort((a,b)=>b.s.goals-a.s.goals||b.s.assists-a.s.assists),rows=tableRows(club);return `<div class="row between"><div><h2 style="margin:0;font-size:20px">成績</h2><p class="small muted">${esc(club.season)} / ${esc(club.league)}</p></div><button class="btn tiny" data-action="otherMatch">＋ 他チーム結果</button></div><div class="tabs">${[['table','順位表'],['players','選手ランキング'],['team','チーム']].map(([k,v])=>`<button data-stats-tab="${k}" class="${statsTab===k?'active':''}">${v}</button>`).join('')}</div>
${statsTab==='table'?`<p class="notice" style="margin:14px 0">入力したリーグ戦の結果だけで作る順位表です。未入力の試合は反映されません。</p>${rows.length?`<div class="card" style="overflow-x:auto;margin-top:12px"><table class="standings"><thead><tr><th>#</th><th>クラブ</th><th>試</th><th>勝</th><th>分</th><th>負</th><th>差</th><th>勝点</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.name===club.club?'me':''}"><td>${i+1}</td><td><b>${esc(r.name)}</b></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gd>0?'+':''}${r.gd}</td><td><b>${r.pts}</b></td></tr>`).join('')}</tbody></table></div>`:empty('♜','順位表はまだありません','リーグ戦と他チームの結果を登録すると更新されます。','試合を登録','addMatch')}`:
statsTab==='players'?`<div class="section-head"><h2>得点・アシストランキング</h2></div>${ranked.length?`<div class="list-card">${ranked.map(({p,s},i)=>`<button class="person-row" data-player="${esc(p.id)}"><span class="small muted" style="width:17px">${i+1}</span>${pic(p.photo,'avatar',p.name)}<span class="grow"><span class="name">${esc(p.name)}</span><span class="detail">${esc(p.pos)} ・ ${s.apps}試合</span></span><span class="chip">${s.goals} G</span><span class="chip neutral">${s.assists} A</span></button>`).join('')}</div>`:empty('♙','選手がいません','選手を登録すると得点ランキングが表示されます。','選手を追加','addPlayer')}`:
`<div class="metrics"><div class="metric"><strong>${t.w}</strong><span>勝利</span></div><div class="metric"><strong>${t.d}</strong><span>引分</span></div><div class="metric"><strong>${t.l}</strong><span>敗戦</span></div><div class="metric"><strong>${t.pts}</strong><span>勝点</span></div></div><div class="card inset" style="margin-top:12px"><h3 style="margin:0 0 16px">シーズン集計</h3><div class="summary-grid"><div><b>${t.gf}</b><span>得点</span></div><div><b>${t.ga}</b><span>失点</span></div><div><b>${t.gd>0?'+':''}${t.gd}</b><span>得失点差</span></div><div><b>${t.p}</b><span>試合</span></div></div></div>`}`}
function socialView(club){let posts=[...club.posts].filter(p=>socialFilter==='all'||p.category===socialFilter).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="row between"><div><h2 style="margin:0;font-size:20px">クラブSNS</h2><p class="small muted">ゲーム内の架空SNSフィード</p></div><button class="btn primary" data-action="addPost">＋ 投稿</button></div><div class="segmented">${[['all','すべて'],['official','公式'],['player','選手'],['fan','ファン']].map(([k,v])=>`<button class="${socialFilter===k?'selected':''}" data-social-filter="${k}">${v}</button>`).join('')}</div>${posts.length?posts.map(p=>postCard(club,p)).join(''):empty('♡','まだ投稿がありません','スタメン発表、GOAL画像、公式ニュース、架空のファン投稿を作ってみましょう。','SNSに投稿','addPost')}`}
function postCard(club,p){let player=club.players.find(x=>x.id===p.playerId),photo=safeImage(p.image),name=player?.name||club.club;let visual='';if(photo)visual=`<div class="post-visual photo"><img src="${photo}" alt="投稿写真"></div>`;else if(p.type==='goal')visual=`<div class="post-visual"><div class="goal-word">GOAL</div>${player?.photo?`<img class="goal-player" src="${safeImage(player.photo)}" alt="">`:''}<div style="position:absolute;bottom:16px;left:16px;font-size:20px;font-weight:850;z-index:2">${esc(name)}</div></div>`;else if(p.type==='lineup')visual=`<div class="post-visual"><div class="lineup-art"><div style="font-size:10px;letter-spacing:.16em">${esc(club.league||'CLUB OFFICIAL')}</div><div class="lineup-title">Starting XI</div><ol>${(p.lineupNames||currentLineupNames(club)).slice(0,11).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${player?.photo?`<img src="${safeImage(player.photo)}" alt="">`:''}</div></div>`;else if(p.type==='result')visual=`<div class="post-visual" style="display:flex;align-items:center;justify-content:center;flex-direction:column"><small style="letter-spacing:.2em;color:#f6c8d9">FULL TIME</small><b style="font-size:58px;margin:10px">${esc(p.score||'FT')}</b><span style="font-size:13px">${esc(p.opponent||club.club)}</span></div>`;
return `<article class="post"><div class="post-head">${pic(p.category==='official'?club.crest:player?.photo,'avatar',p.category==='official'?club.club:name)}<div class="grow"><b>${p.category==='official'?esc(club.club):p.category==='fan'?'FAN COMMUNITY':esc(player?.name||'選手')}</b><span>${p.category==='official'?'公式':p.category==='fan'?'ファン':'選手'}　・　${shortDate(p.date)}</span></div><span class="chip neutral">${esc((p.type==='goal'?'GOAL':p.type==='lineup'?'LINEUP':'POST'))}</span></div><div class="post-caption"><b>${esc(p.title||'')}</b>${p.body?`<div style="white-space:pre-wrap;margin-top:5px">${esc(p.body)}</div>`:''}</div>${visual}<div class="post-foot"><button class="post-action ${p.liked?'liked':''}" data-like="${esc(p.id)}">${p.liked?'♥':'♡'} ${n(p.likes)+(p.liked?1:0)} いいね</button><button class="post-action" data-comment="${esc(p.id)}">♧ ${(p.comments||[]).length} コメント</button><span style="margin-left:auto;font-size:10px">${shortDate(p.date)}</span></div>${p.expanded?`<div class="comment">${(p.comments||[]).map(x=>`<p style="margin:6px 0">${esc(x)}</p>`).join('')||'まだコメントはありません。'}<button class="btn tiny" data-add-comment="${esc(p.id)}">＋ コメントを書く</button></div>`:''}</article>`}
function currentLineupNames(club){return (club.tactics?.slots||[]).map(x=>club.players.find(p=>p.id===x.playerId)?.name).filter(Boolean)}
function moreView(club){return `<div class="section-head" style="margin-top:0"><h2>クラブを管理</h2><small>スマホ版</small></div><div class="list-card">${[['club','🏟️','クラブ紹介','エンブレム・カバー・クラブの歴史'],['tactics','⌗','戦術・フォーメーション','先発11人と位置を自由に配置'],['transfers','⇄','移籍履歴','加入・退団をまとめて管理'],['scout','☆','スカウトセンター','おすすめ選手・若手・お気に入り'],['settings','⚙','データ管理','キャリア切替・バックアップ・設定']].map(([k,ico,title,desc])=>`<button class="menu-row" data-sub="${k}"><span>${ico}　<b>${title}</b><span class="desc" style="padding-left:29px">${desc}</span></span><span class="right-arrow">›</span></button>`).join('')}</div><div class="notice">ログインした本人専用のクラウドに自動保存します。通信が切れた場合に備えてJSONバックアップも残しておきましょう。</div>`}
function clubView(club){return `<section class="hero" style="min-height:240px">${safeImage(club.cover)?`<img class="hero-cover" src="${safeImage(club.cover)}">`:''}${crest(club)}<h1>${esc(club.club)}</h1><div class="hero-sub">${esc(club.league)} ・ ${esc(club.game)}</div></section><div class="section-head"><h2>クラブプロフィール</h2><button class="btn tiny" data-action="editClub">✎ 編集</button></div><div class="card inset"><div class="info-grid">${info(club.manager||'—','監督')}${info(club.stadium||'—','スタジアム')}${info(club.season,'シーズン')}</div></div><div class="section-head"><h2>クラブ紹介</h2></div><div class="card inset"><p style="font-size:13px;line-height:2;white-space:pre-wrap;margin:0">${esc(club.bio||'まだクラブ紹介がありません。創設の理由や目指すサッカー、クラブの物語を登録しましょう。')}</p></div><div class="section-head"><h2>スカッド</h2><button class="btn tiny" data-nav="squad">すべて見る ›</button></div><div class="card inset"><strong>${club.players.length} 名</strong><p class="small muted">選手登録した情報が反映されます。</p></div>`}
const formationPositions={
'4-3-3':[[50,12],[20,27],[80,27],[30,50],[50,54],[70,50],[12,75],[38,80],[62,80],[88,75],[50,93]],
'4-2-3-1':[[50,14],[18,32],[50,34],[82,32],[35,56],[65,56],[12,75],[38,80],[62,80],[88,75],[50,93]],
'4-4-2':[[37,17],[63,17],[14,47],[38,52],[62,52],[86,47],[12,75],[38,80],[62,80],[88,75],[50,93]],
'3-5-2':[[37,15],[63,15],[15,43],[38,42],[62,42],[85,43],[50,61],[25,79],[50,81],[75,79],[50,93]]};
function ensureSlots(club){if(!club.tactics)club.tactics={formation:'4-3-3',slots:[]};let f=club.tactics.formation||'4-3-3',pts=formationPositions[f]||formationPositions['4-3-3'];if(!Array.isArray(club.tactics.slots)||club.tactics.slots.length!==11){let old=(club.tactics.slots||[]).map(s=>s.playerId);club.tactics.slots=pts.map(([x,y],i)=>({x,y,playerId:old[i]||''}))}return club.tactics.slots}
function tacticsView(club){const slots=ensureSlots(club);return `<div class="row between"><div><h2 style="font-size:19px;margin:0">戦術ボード</h2><p class="small muted">選手をドラッグして配置変更</p></div><button class="btn tiny" data-action="tacticReset">配置リセット</button></div><div class="segmented" style="margin:13px 0">${Object.keys(formationPositions).map(f=>`<button class="${club.tactics.formation===f?'selected':''}" data-formation="${f}">${f}</button>`).join('')}</div><div class="pitch" id="pitch"><div class="penalty top"></div><div class="penalty bottom"></div>${slots.map((s,i)=>{let p=club.players.find(p=>p.id===s.playerId);return `<button class="pitch-player" data-slot="${i}" style="left:${clamp(s.x,4,96)}%;top:${clamp(s.y,5,95)}%"><small>${i===10?'GK':i<3?'FW':i<6?'MF':'DF'}</small><b>${p?esc(p.name):'＋選手'}</b></button>`}).join('')}</div><p class="notice" style="margin-top:13px">選手の枠をタップすると割り当てができます。長押しせず指で動かすと自由に位置を調整できます。端末内に自動保存されます。</p><div class="section-head"><h2>先発登録 ${slots.filter(x=>x.playerId).length}/11</h2><button class="btn tiny" data-action="lineupPost">SNSにスタメン投稿</button></div><div class="card inset"><div class="row wrap">${slots.filter(x=>x.playerId).map(x=>{let p=club.players.find(p=>p.id===x.playerId);return `<span class="chip">${esc(p?.num||'—')} ${esc(p?.name||'')}</span>`}).join('')||'<span class="small muted">まだ選手が設定されていません。</span>'}</div></div>`}
function transfersView(club){return `<div class="row between"><h2 style="margin:0;font-size:19px">移籍履歴</h2><button class="btn primary" data-action="addTransfer">＋ 移籍登録</button></div>${club.transfers.length?`<div class="list-card">${[...club.transfers].reverse().map(t=>`<div class="person-row"><span style="font-size:22px">${t.type==='加入'?'↘':'↗'}</span><span class="grow"><b style="font-size:13px">${esc(t.player)}</b><span class="detail">${esc(t.type)} ・ ${esc(t.club||'—')} ・ ${shortDate(t.date)}</span></span><span class="chip neutral">${esc(t.fee||'—')}</span></div>`).join('')}</div>`:empty('⇄','移籍履歴はまだありません','加入・退団・移籍金を記録できます。','移籍を登録','addTransfer')}`}
const scoutFC26=[['Gilberto Mora','CAM','若手','メキシコ'],['Artem Stepanov','ST','若手','ウクライナ'],['Pau Cubarsí','CB','若手','スペイン'],['Lamine Yamal','RW','即戦力','スペイン'],['Endrick','ST','若手','ブラジル'],['Désiré Doué','LW','若手','フランス'],['Jorrel Hato','CB','若手','オランダ'],['Dean Huijsen','CB','若手','スペイン'],['Kenan Yıldız','CAM','若手','トルコ'],['Estevão','RW','若手','ブラジル'],['Ethan Nwaneri','CAM','若手','イングランド'],['João Neves','CM','即戦力','ポルトガル'],['Warren Zaïre-Emery','CM','若手','フランス'],['Milos Kerkez','LB','若手','ハンガリー'],['Benjamin Šeško','ST','若手','スロベニア'],['Jamal Musiala','CAM','即戦力','ドイツ'],['Florian Wirtz','CAM','即戦力','ドイツ'],['Michael Olise','RW','即戦力','フランス']];
const scoutFIFA17=[['Kylian Mbappé','ST','若手','フランス'],['Ousmane Dembélé','RW','若手','フランス'],['Gianluigi Donnarumma','GK','若手','イタリア'],['Gabriel Jesus','ST','若手','ブラジル'],['Renato Sanches','CM','若手','ポルトガル'],['Marco Asensio','RW','若手','スペイン'],['Youri Tielemans','CM','若手','ベルギー'],['Dele Alli','CAM','即戦力','イングランド'],['Kingsley Coman','LW','若手','フランス'],['Christian Pulisic','RW','若手','アメリカ'],['Leroy Sané','LW','若手','ドイツ'],['Timo Werner','ST','若手','ドイツ'],['Marcus Rashford','ST','若手','イングランド'],['Anthony Martial','LW','即戦力','フランス']];
function allScouts(club){let arr=/fifa\s?17/i.test(club.game)?scoutFIFA17:scoutFC26;return [...arr.map(p=>({id:'builtin-'+p[0],name:p[0],pos:p[1],type:p[2],nation:p[3]})),...(club.customScouts||[])]}
function scoutView(club){let a=allScouts(club).filter(p=>(scoutFilter==='すべて'||scoutFilter==='お気に入り'&&(club.favorites||[]).includes(p.id)||p.type===scoutFilter)&&(!scoutSearch||p.name.toLowerCase().includes(scoutSearch.toLowerCase())));return `<div class="row between"><div><h2 style="margin:0;font-size:19px">スカウトセンター</h2><p class="small muted">${esc(club.game)} 向け参考候補</p></div><button class="btn tiny" data-action="addScout">＋ 候補追加</button></div><div class="segmented" style="margin:14px 0">${['すべて','若手','即戦力','お気に入り'].map(k=>`<button data-scout-filter="${k}" class="${scoutFilter===k?'selected':''}">${k}</button>`).join('')}</div><div class="notice">おすすめは参考用の名前リストです。ゲーム内の収録・能力・移籍金は実際のセーブで確認してください。</div><div class="list-card">${a.map(p=>`<div class="scout-row"><div class="grow"><div class="scout-name">${esc(p.name)} <span class="chip">${esc(p.type)}</span></div><div class="scout-note">${esc(p.pos)} ・ ${esc(p.nation)}</div></div><button class="btn tiny ${club.favorites?.includes(p.id)?'primary':''}" data-fav="${esc(p.id)}">${club.favorites?.includes(p.id)?'★':'☆'}</button><button class="btn tiny" data-recruit="${esc(p.id)}">＋選手</button></div>`).join('')||`<div class="inset small muted">該当する選手はいません。</div>`}</div>`}
function settingsView(club){if(readOnly)return `<div class="section-head"><h2>クラブ・設定</h2></div><div class="card inset"><strong>公開閲覧モード</strong><p class="small muted">誰でも選手名鑑、試合、順位表、SNSを閲覧できます。データの追加・編集は管理者だけが行います。</p><button class="btn primary wide" data-action="login">🔐 管理者ログイン</button></div><div class="section-head"><h2>キャリア切替</h2></div><div class="list-card">${app.careers.map(x=>`<button class="menu-row" data-career="${esc(x.id)}"><span><b>${esc(x.club)}</b><span class="desc">${esc(x.game)} ・ ${esc(x.season)}</span></span><span class="right-arrow">›</span></button>`).join('')}</div>`;return `<div class="section-head" style="margin-top:0"><h2>データ管理</h2></div><div class="card inset"><strong>☁ クラウドに自動保存</strong><p class="small muted" style="line-height:1.8">ログイン中のアカウント専用のFirebaseに自動保存します。オフライン時は端末内に一時保存し、再接続後に同期を試みます。JSONバックアップもおすすめします。</p><p class="small">ログイン中：<b>${esc(cloud?.email||'')}</b></p><div class="row wrap"><button class="btn primary" data-action="export">↓ JSONバックアップ</button><button class="btn" data-action="import">↑ 復元</button></div><input type="file" id="import-file" accept=".json,application/json" hidden></div><div class="card inset" style="margin-top:12px"><strong>アカウントと同期</strong><p class="small muted">同期状態：<span id="sync-state">${esc(cloud?.status||'未接続')}</span></p><div class="row wrap"><button class="btn" data-action="shareConfig">別端末用の接続リンク</button><button class="btn" data-action="reloadCloud">最新のサーバー記録を取得</button><button class="btn danger" data-action="logout">ログアウト</button></div></div><div class="section-head"><h2>キャリアを切り替え</h2><button class="btn tiny" data-action="newCareer">＋ 新規</button></div><div class="list-card">${app.careers.map(x=>`<button class="menu-row" data-career="${esc(x.id)}"><span><b>${esc(x.club)}</b><span class="desc">${esc(x.game)} ・ ${esc(x.season)}</span></span>${x.id===club.id?'<span class="chip">選択中</span>':'<span class="right-arrow">›</span>'}</button>`).join('')}</div><div class="section-head"><h2>選択中のクラブ</h2></div><div class="row wrap"><button class="btn" data-action="editClub">✎ クラブ編集</button><button class="btn danger" data-action="deleteCareer">クラブを削除</button></div><div class="section-head"><h2>ホーム画面に追加</h2></div><div class="card inset"><p class="small muted" style="line-height:1.8;margin:0">Safariでサイトを開き、共有メニューの「ホーム画面に追加」を選択します。以後はホーム画面のアイコンから起動してください。<br>※ ホーム画面アプリで初回設定が再度必要な場合は「別端末用の接続リンク」から設定し、同じアカウントでログインしてください。</p></div><p class="small muted" style="margin-top:17px">保存方法：Firebase（サーバー）＋ ${persistMethod==='indexedDB'?'IndexedDB（端末キャッシュ）':'localStorage（端末キャッシュ）'}</p>`}
function field(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="mf-${name}">${label}</label><input id="mf-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function wide(text){return `<p class="small muted" style="line-height:1.8">${text}</p>`}
function area(name,label,value=''){return `<div class="form-field full"><label>${label}</label><textarea name="${name}">${esc(value)}</textarea></div>`}
function select(name,label,options,value=''){return `<div class="form-field"><label>${label}</label><select name="${name}">${options.map(x=>{let [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function photoField(name,label){return `<div class="form-field full"><label>${label}</label><input name="${name}" type="file" accept="image/*"></div>`}
function showModal(title,body,onSave,button='保存する'){currentModalSave=onSave;modalRoot.innerHTML=`<div class="modal-bg"><div class="modal-panel"><div class="modal-bar"></div><div class="modal-title"><h2>${title}</h2><button class="close" data-close>閉じる ✕</button></div><form id="modal-form"><div class="form-grid">${body}</div><div class="modal-actions"><button type="button" class="btn" data-close>キャンセル</button><button type="submit" class="btn primary" id="modal-submit">${button}</button></div></form></div></div>`;let first=$('input:not([type=file]),select',modalRoot);if(first&&!matchMedia('(pointer:coarse)').matches)first.focus()}
function closeModal(){modalRoot.innerHTML='';currentModalSave=null;matchDraft=null}
const formVal=(form,name)=>form.elements.namedItem(name)?.value?.trim()||'';
const formFile=(form,name)=>form.elements.namedItem(name)?.files?.[0];
async function readPhoto(file,max=640){
 if(!file)return '';
 if(!file.type.startsWith('image/')){toast('画像ファイルを選んでください');return ''}
 return new Promise(res=>{const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{
  let scale=Math.min(1,Math.min(max,900)/Math.max(im.width,im.height)),quality=.72,output='';
  const cv=document.createElement('canvas');
  for(let attempt=0;attempt<8;attempt++){
   cv.width=Math.max(1,Math.round(im.width*scale));cv.height=Math.max(1,Math.round(im.height*scale));
   const ctx=cv.getContext('2d');ctx.fillStyle='#29222b';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(im,0,0,cv.width,cv.height);
   output=cv.toDataURL('image/jpeg',quality);if(output.length<620000)break;
   scale*=.81;quality=Math.max(.43,quality-.06);
  }
  URL.revokeObjectURL(url);
  if(output.length>=700000){toast('写真が大きすぎます。別の画像をお試しください');res('');return}
  res(output);
 };im.onerror=()=>{URL.revokeObjectURL(url);toast('写真を読み込めませんでした');res('')};im.src=url});
}
function newCareerModal(){if(readOnly)return;showModal('新しいキャリア',`${select('game','ゲーム',['FC26','FC25','FC24','FIFA23','FIFA22','FIFA19','FIFA18','FIFA17','その他'],'FC26')}${field('season','シーズン','2026/27')}<div class="full">${field('club','クラブ名','','text','required')}</div><div class="full">${field('league','所属リーグ','Premier League')}</div>`,form=>{let name=formVal(form,'club');if(!name){toast('クラブ名を入力してください');return false}let x=createCareer(formVal(form,'game'),name,formVal(form,'season'),formVal(form,'league'));app.careers.push(x);app.activeId=x.id;activePage='home';subPage='';playerId=null;saveSoon();return true},'キャリアを作成')}
function editClub(){let club=c();showModal('クラブ紹介を編集',`<div class="full">${field('club','クラブ名',club.club,'text','required')}</div>${field('game','ゲーム',club.game)}${field('season','シーズン',club.season)}<div class="full">${field('league','リーグ',club.league)}</div>${field('manager','監督名',club.manager)}${field('stadium','スタジアム名',club.stadium)}${area('bio','クラブの歴史・紹介文',club.bio)}${photoField('crest','エンブレム画像（変更する場合のみ）')}${photoField('cover','カバー画像（変更する場合のみ）')}`,async form=>{club.club=formVal(form,'club')||club.club;for(let x of ['game','season','league','manager','stadium','bio'])club[x]=formVal(form,x);for(let x of ['crest','cover']){let file=formFile(form,x);if(file)club[x]=await readPhoto(file,x==='cover'?1100:360)}saveSoon();return true})}
const posOptions=['GK','CB','LB','RB','LWB','RWB','CDM','CM','CAM','LM','RM','LW','RW','ST','CF'];
function addPlayer(existing=null){const club=c(),editing=!!existing,p=existing||{};showModal(editing?'選手プロフィールを編集':'新しい選手を登録',`<div class="full">${field('name','選手名',p.name||'','text','required')}</div>${select('pos','ポジション',posOptions,p.pos||'ST')}${field('num','背番号',p.num||'','number','min="0" max="99"')}${field('nation','国籍',p.nation||'')}${field('age','年齢',p.age||'','number','min="0" max="80"')}${field('height','身長（cm）',p.height||'','number')}${field('weight','体重（kg）',p.weight||'','number')}${select('foot','利き足',['右','左','両足','未設定'],p.foot||'未設定')}${field('ovr','総合値 OVR',p.ovr||'','number','min="1" max="99"')}${area('bio','選手紹介・特徴',p.bio||'')}${photoField('photo','顔写真（スマホから選択）')}<div class="full"><div class="notice">写真は縮小してクラウド保存します。現在のシーズンで試合から集計できない過去の記録がある場合のみ、下の手動加算欄を使ってください。</div></div>${field('manualApps','手動加算：出場数',p.manual?.apps||0,'number','min="0"')}${field('manualGoals','手動加算：得点',p.manual?.goals||0,'number','min="0"')}${field('manualAssists','手動加算：アシスト',p.manual?.assists||0,'number','min="0"')}${field('manualMinutes','手動加算：出場分',p.manual?.minutes||0,'number','min="0"')}`,async form=>{let name=formVal(form,'name');if(!name){toast('選手名を入力してください');return false}let obj=editing?p:{id:uid()};for(let k of ['name','pos','num','nation','age','height','weight','foot','ovr','bio'])obj[k]=formVal(form,k);obj.manual={apps:n(formVal(form,'manualApps')),goals:n(formVal(form,'manualGoals')),assists:n(formVal(form,'manualAssists')),minutes:n(formVal(form,'manualMinutes'))};let file=formFile(form,'photo');if(file)obj.photo=await readPhoto(file,720);if(!editing)club.players.push(obj);saveSoon();return true})}
function otherMatchModal(){showModal('他チームの結果',`${field('date','日付',today(),'date')}<div class="full">${field('home','ホームチーム','','text','required')}</div><div class="full">${field('away','アウェイチーム','','text','required')}</div>${field('hg','ホーム得点','0','number','min="0"')}${field('ag','アウェイ得点','0','number','min="0"')}`,form=>{let home=formVal(form,'home'),away=formVal(form,'away');if(!home||!away||home.toLowerCase()===away.toLowerCase()){toast('異なる2チームの名前を入力してください');return false}c().otherMatches.push({id:uid(),date:formVal(form,'date'),home,away,hg:n(formVal(form,'hg')),ag:n(formVal(form,'ag'))});saveSoon();return true})}
function transferModal(){showModal('移籍履歴を登録',`${field('date','日付',today(),'date')}${select('type','移籍区分',['加入','退団','期限付き加入','期限付き退団'])}<div class="full">${field('player','選手名','','text','required')}</div><div class="full">${field('club','移籍元・移籍先クラブ')}</div><div class="full">${field('fee','移籍金・備考','','text')}</div>`,form=>{if(!formVal(form,'player')){toast('選手名を入力してください');return false}c().transfers.push({id:uid(),date:formVal(form,'date'),type:formVal(form,'type'),player:formVal(form,'player'),club:formVal(form,'club'),fee:formVal(form,'fee')});saveSoon();return true})}
function postModal(preselect=null){let club=c();showModal('SNS投稿を作成',`${select('category','投稿者',[['official','クラブ公式'],['player','選手'],['fan','ファン']],'official')}${select('type','投稿デザイン',[['text','通常投稿'],['goal','GOALポスター'],['lineup','Starting XI'],['result','試合結果']],preselect||'text')}<div class="full">${field('title','見出し','','text','required')}</div>${area('body','本文・コメント')}${select('player','登場する選手',[['','選手なし'],...club.players.map(p=>[p.id,p.name])])}${field('date','投稿日',today(),'date')}${photoField('image','投稿画像（任意・画像がある場合は優先表示）')}`,async form=>{let title=formVal(form,'title');if(!title){toast('見出しを入力してください');return false}let file=formFile(form,'image'),image=file?await readPhoto(file,1000):'';club.posts.push({id:uid(),title,body:formVal(form,'body'),date:formVal(form,'date'),category:formVal(form,'category'),type:formVal(form,'type'),playerId:formVal(form,'player'),likes:0,comments:[],liked:false,image,lineupNames:currentLineupNames(club)});saveSoon();socialFilter='all';return true},'投稿する')}
function lineupPost(){let club=c(),names=currentLineupNames(club);if(!names.length){toast('先に戦術ボードに選手を配置してください');return}club.posts.push({id:uid(),date:today(),category:'official',type:'lineup',title:'Starting XI',body:`${club.club} の先発メンバーを発表！`,lineupNames:names,likes:0,comments:[],playerId:club.tactics.slots.find(x=>x.playerId)?.playerId||''});activePage='social';subPage='';saveSoon();render();toast('スタメン投稿を作成しました')}
function addScout(){showModal('スカウト候補を追加',`<div class="full">${field('name','選手名','','text','required')}</div>${select('pos','ポジション',posOptions,'ST')}${select('type','分類',['若手','即戦力','穴場'],'若手')}<div class="full">${field('nation','国籍')}</div>`,form=>{let name=formVal(form,'name');if(!name)return false;c().customScouts.push({id:uid(),name,pos:formVal(form,'pos'),type:formVal(form,'type'),nation:formVal(form,'nation')});saveSoon();return true})}
function showSlotEditor(i){let club=c(),slot=ensureSlots(club)[i];showModal(`ポジション ${i+1} を編集`,`${select('player','配置する選手',[['','空欄'],...club.players.map(p=>[p.id,`#${p.num||'–'} ${p.name} (${p.pos})`])],slot.playerId||'')}<div class="full">${wide('選手を変更して保存します。位置はピッチ上でドラッグすると自由に調整できます。')}</div>`,form=>{let id=formVal(form,'player');if(id){for(let [j,s] of club.tactics.slots.entries())if(j!==i&&s.playerId===id)s.playerId=''}slot.playerId=id;saveSoon();return true})}
function memberEditor(){if(!matchDraft)return '';let club=c();return club.players.map(p=>{let r=matchDraft[p.id]||{role:'',goals:0,assists:0,minutes:0};return `<div class="member-edit"><strong>${esc(p.name)}</strong><button type="button" class="step" data-member-role="${esc(p.id)}">${({start:'先発',sub:'途中出場',bench:'ベンチ'})[r.role]||'未登録'}</button><span class="micro muted">G</span><button type="button" class="step" data-member-change="${esc(p.id)}:goals:-1">−</button><span class="count">${n(r.goals)}</span><button type="button" class="step" data-member-change="${esc(p.id)}:goals:1">＋</button><span class="micro muted">A</span><button type="button" class="step" data-member-change="${esc(p.id)}:assists:-1">−</button><span class="count">${n(r.assists)}</span><button type="button" class="step" data-member-change="${esc(p.id)}:assists:1">＋</button><input aria-label="出場時間" placeholder="分" type="number" min="0" max="130" value="${n(r.minutes)}" data-member-minutes="${esc(p.id)}" style="width:50px;min-width:50px;background:#18141c;border:1px solid #624b5e;border-radius:7px;color:#fff;padding:5px;font-size:11px"></div>`}).join('')}
function matchModal(){let club=c();matchDraft={};for(let s of ensureSlots(club))if(s.playerId)matchDraft[s.playerId]={role:'start',goals:0,assists:0,minutes:90};showModal('試合結果を登録',`${field('date','試合日',today(),'date')}<div class="full">${field('opponent','対戦相手','','text','required')}</div>${field('competition','大会',club.league)}${select('venue','会場',[['home','ホーム'],['away','アウェイ']],'home')}${field('gf','自クラブ得点','0','number','min="0"')}${field('ga','相手得点','0','number','min="0"')}${select('leagueMatch','順位表に反映する？',[['yes','はい：リーグ戦'],['no','いいえ：カップ戦']],'yes')}${field('possession','支配率 %','','number','min="0" max="100"')}${field('shots','シュート数','','number','min="0"')}${field('onTarget','枠内シュート','','number','min="0"')}${field('xg','xG','','number','step="0.01" min="0"')}${area('notes','試合メモ')}<div class="full"><div class="section-head" style="margin:10px 0"><h2>先発・出場・得点</h2><small>タップで編集</small></div><p class="small muted">状態をタップすると「先発→途中出場→ベンチ→未登録」に変わります。G＝得点、A＝アシスト、右の数字＝出場分です。</p><div id="member-list" style="display:grid;gap:8px">${memberEditor()}</div></div>${photoField('image','試合のスクリーンショット（任意）')}`,async form=>{let opponent=formVal(form,'opponent');if(!opponent){toast('対戦相手を入力してください');return false}let perf=[];for(let [id,r] of Object.entries(matchDraft)){if(r.role||r.goals||r.assists)perf.push({id,role:r.role||'sub',goals:n(r.goals),assists:n(r.assists),minutes:n(r.minutes)})}let file=formFile(form,'image');let m={id:uid(),date:formVal(form,'date'),opponent,competition:formVal(form,'competition'),venue:formVal(form,'venue'),gf:n(formVal(form,'gf')),ga:n(formVal(form,'ga')),leagueMatch:formVal(form,'leagueMatch')==='yes',possession:formVal(form,'possession'),shots:formVal(form,'shots'),onTarget:formVal(form,'onTarget'),xg:formVal(form,'xg'),notes:formVal(form,'notes'),players:perf,image:file?await readPhoto(file,1024):''};club.matches.push(m);club.posts.push({id:uid(),date:m.date,category:'official',type:'result',title:'FULL TIME',body:`${club.club} ${m.gf} - ${m.ga} ${m.opponent}`,score:`${m.gf} - ${m.ga}`,opponent:m.opponent,likes:0,comments:[],liked:false});saveSoon();return true},'試合を保存')}
function matchDetail(id){let club=c(),m=club.matches.find(x=>x.id===id);if(!m)return;let perf=(m.players||[]).map(x=>({x,p:club.players.find(p=>p.id===x.id)})).filter(x=>x.p);showModal('試合詳細',`<div class="full" style="text-align:center"><span class="chip">${esc(m.competition)}</span><p class="small muted">${shortDate(m.date)}　${m.venue==='away'?'アウェイ':'ホーム'}</p><h2 style="font-size:20px">${esc(club.club)} vs ${esc(m.opponent)}</h2><div style="font-weight:950;font-size:38px">${n(m.gf)} - ${n(m.ga)}</div>${resultLabel(m)}</div><div class="full"><hr class="line"><h3 style="font-size:15px">試合スタッツ</h3>${[['支配率',m.possession,'%'],['シュート',m.shots,''],['枠内シュート',m.onTarget,''],['xG',m.xg,'']].map(([a,b,unit])=>b!==''?`<div class="row between" style="padding:8px 0;border-bottom:1px solid var(--stroke)"><span class="small muted">${a}</span><strong>${esc(b)}${unit}</strong></div>`:'').join('')}<h3 style="font-size:15px">選手記録</h3>${perf.map(({x,p})=>`<div class="row between" style="padding:7px 0"><span class="small">${esc(p.name)} <span class="muted">${x.role==='start'?'先発':x.role==='bench'?'ベンチ':'途中出場'}</span></span><span class="small">${n(x.goals)}G ${n(x.assists)}A / ${n(x.minutes)}′</span></div>`).join('')||'<p class="small muted">選手記録なし</p>'}${safeImage(m.image)?`<img src="${safeImage(m.image)}" style="width:100%;margin-top:10px;border-radius:10px" alt="試合のスクリーンショット">`:''}${m.notes?`<p class="small muted" style="white-space:pre-wrap;line-height:1.8">${esc(m.notes)}</p>`:''}<button type="button" class="btn danger wide" style="margin-top:15px" data-del-match="${esc(m.id)}">この試合を削除</button></div>`,()=>true,'閉じる')}
function exportJSON(){saveNow();let blob=new Blob([JSON.stringify(app,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.download='football-career-hub-mobile-backup-'+today()+'.json';a.href=url;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);toast('バックアップを作成しました')}
function importJSON(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{let data=JSON.parse(r.result);if(!data||!Array.isArray(data.careers)||data.version!==1)throw Error('invalid');if(!confirm('現在のすべての記録をバックアップの内容で置き換えますか？'))return;app=data;app.activeId=app.careers.find(c=>c.id===app.activeId)?.id||app.careers[0]?.id||null;activePage='home';subPage='';playerId=null;saveNow().then(()=>{render();toast('バックアップを復元しました')})}catch(e){toast('このアプリのJSONバックアップではありません')}};r.readAsText(file)}
function removeCareer(){if(!confirm('選択中のキャリアを削除しますか？\nこの操作は元に戻せません。'))return;app.careers=app.careers.filter(x=>x.id!==app.activeId);app.activeId=app.careers[0]?.id||null;activePage='home';subPage='';saveSoon();render();toast('キャリアを削除しました')}
function switchCareerModal(){showModal('キャリアを選択',`<div class="full"><p class="small muted">保存済みのクラブ</p>${app.careers.map(x=>`<button type="button" class="menu-row" data-career="${esc(x.id)}"><span><b>${esc(x.club)}</b><span class="desc">${esc(x.game)} ・ ${esc(x.season)}</span></span><span>›</span></button>`).join('')}</div>`,()=>true,'閉じる');if(!readOnly){const btn=document.createElement('button');btn.type='button';btn.className='btn primary wide';btn.textContent='＋ 新しいキャリア';btn.onclick=()=>newCareerModal();$('#modal-form .form-grid',modalRoot).appendChild(btn)}}
root.addEventListener('submit',e=>{if(readOnly)return;if(e.target.id==='welcome-form'){e.preventDefault();let f=e.target,x=createCareer(formVal(f,'game'),formVal(f,'club'),formVal(f,'season'),formVal(f,'league'));app.careers=[x];app.activeId=x.id;saveSoon();render();toast('クラブを作成しました！')}});
root.addEventListener('click',async e=>{
let b=e.target.closest('button');if(!b)return;
if(b.dataset.action==='login'){window.FCHAuth?.open();return}
if(readOnly&&(b.dataset.fav||b.dataset.recruit||b.dataset.like||b.dataset.addComment||b.dataset.delOther||b.dataset.formation||b.dataset.slot!==undefined||['addPlayer','editPlayer','addMatch','otherMatch','addPost','lineupPost','editClub','addTransfer','addScout','newCareer','deleteCareer','save','import','logout','tacticReset'].includes(b.dataset.action))){toast('編集には管理者ログインが必要です');return}
if(b.dataset.nav){setPage(b.dataset.nav);return}
if(b.dataset.sub){openSub(b.dataset.sub);return}
if(b.dataset.player){openPlayer(b.dataset.player);return}
if(b.dataset.playerTab){playerTab=b.dataset.playerTab;render();return}
if(b.dataset.statsTab){statsTab=b.dataset.statsTab;render();return}
if(b.dataset.socialFilter){socialFilter=b.dataset.socialFilter;render();return}
if(b.dataset.squadFilter){squadFilter=b.dataset.squadFilter;render();return}
if(b.dataset.scoutFilter){scoutFilter=b.dataset.scoutFilter;render();return}
if(b.dataset.formation){let x=c();x.tactics.formation=b.dataset.formation;let pts=formationPositions[x.tactics.formation];ensureSlots(x);x.tactics.slots.forEach((s,i)=>{s.x=pts[i][0];s.y=pts[i][1]});saveSoon();render();return}
if(b.dataset.slot!==undefined){if(Date.now()-(drag?.ended||0)>450)showSlotEditor(n(b.dataset.slot));return}
if(b.dataset.match){matchDetail(b.dataset.match);return}
if(b.dataset.career){app.activeId=b.dataset.career;activePage='home';subPage='';playerId=null;saveSoon();render();return}
if(b.dataset.fav){let x=c();x.favorites=x.favorites||[];if(x.favorites.includes(b.dataset.fav))x.favorites=x.favorites.filter(a=>a!==b.dataset.fav);else x.favorites.push(b.dataset.fav);saveSoon();render();return}
if(b.dataset.recruit){let x=c(),p=allScouts(x).find(q=>q.id===b.dataset.recruit);if(!p)return;if(x.players.some(z=>z.name.toLowerCase()===p.name.toLowerCase())){toast('すでにスカッドに登録されています');return}x.players.push({id:uid(),name:p.name,pos:p.pos,nation:p.nation,num:'',photo:'',bio:'',age:'',manual:{apps:0,goals:0,assists:0,minutes:0}});saveSoon();toast('スカッドに追加しました');return}
if(b.dataset.like){let post=c().posts.find(p=>p.id===b.dataset.like);if(post){post.liked=!post.liked;saveSoon();render()}return}
if(b.dataset.comment){let post=c().posts.find(p=>p.id===b.dataset.comment);if(post){post.expanded=!post.expanded;render()}return}
if(b.dataset.addComment){let post=c().posts.find(p=>p.id===b.dataset.addComment);if(!post)return;let txt=prompt('架空SNSのコメントを入力');if(txt?.trim()){post.comments=post.comments||[];post.comments.push(txt.trim());saveSoon();render()}return}
if(b.dataset.delOther){if(confirm('この他チームの結果を削除しますか？')){c().otherMatches=c().otherMatches.filter(m=>m.id!==b.dataset.delOther);saveSoon();render()}return}
const a=b.dataset.action;
if(a==='save'){if(await saveNow())toast('保存しました');return}
if(a==='switch'){switchCareerModal();return}
if(a==='back'){back();return}
if(a==='addPlayer'){addPlayer();return}
if(a==='editPlayer'){let p=c().players.find(p=>p.id===(b.dataset.id||playerId));if(p)addPlayer(p);return}
if(a==='addMatch'){matchModal();return}
if(a==='otherMatch'){otherMatchModal();return}
if(a==='addPost'){postModal();return}
if(a==='lineupPost'){lineupPost();return}
if(a==='editClub'){editClub();return}
if(a==='addTransfer'){transferModal();return}
if(a==='addScout'){addScout();return}
if(a==='newCareer'){newCareerModal();return}
if(a==='deleteCareer'){removeCareer();return}
if(a==='export'){exportJSON();return}
if(a==='import'){$('#import-file')?.click();return}
if(a==='logout'){if(cloud&&confirm('ログアウトしますか？'))await cloud.logout();return}
if(a==='shareConfig'){if(!cloud)return;const link=cloud.getTransferURL();try{await navigator.clipboard.writeText(link);toast('別端末用リンクをコピーしました')}catch(e){prompt('以下のリンクをコピーしてください',link)}return}
if(a==='reloadCloud'){if(!cloud)return;if(!confirm('サーバー側の記録を読み直します。端末内の未同期変更がある場合は失われます。先にバックアップを保存しましたか？'))return;try{await cloud.reloadServer();toast('サーバーの記録を取得しました')}catch(e){toast('読み込みできませんでした。通信状況をご確認ください')}return}
if(a==='tacticReset'){let x=c(),p=formationPositions[x.tactics.formation]||formationPositions['4-3-3'];ensureSlots(x).forEach((s,i)=>{s.x=p[i][0];s.y=p[i][1]});saveSoon();render();return}
});
root.addEventListener('change',e=>{if(readOnly)return;if(e.target.id==='import-file'){importJSON(e.target.files[0]);e.target.value=''}});
modalRoot.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){if(e.target.classList.contains('modal-bg'))closeModal();return}if(b.hasAttribute('data-close')){closeModal();return}
if(b.dataset.career){app.activeId=b.dataset.career;activePage='home';subPage='';playerId=null;closeModal();saveSoon();render();return}
if(readOnly&&b.dataset.delMatch){toast('編集にはログインが必要です');return}if(b.dataset.delMatch){if(confirm('この試合と関連する成績を削除しますか？')){c().matches=c().matches.filter(m=>m.id!==b.dataset.delMatch);closeModal();saveSoon();render();toast('試合を削除しました')}return}
if(readOnly&&b.dataset.memberRole)return;if(b.dataset.memberRole){let id=b.dataset.memberRole,r=matchDraft?.[id];if(!r)return;const order=['','start','sub','bench'],idx=order.indexOf(r.role||'');r.role=order[(idx+1)%order.length];r.minutes=r.role==='start'?90:r.role==='sub'?30:0;$('#member-list',modalRoot).innerHTML=memberEditor();return}
if(readOnly&&b.dataset.memberChange)return;if(b.dataset.memberChange){let [id,key,diff]=b.dataset.memberChange.split(':'),r=matchDraft?.[id];if(!r)return;r[key]=Math.max(0,n(r[key])+n(diff));$('#member-list',modalRoot).innerHTML=memberEditor();return}
});
modalRoot.addEventListener('input',e=>{if(readOnly)return;const el=e.target;if(el.dataset.memberMinutes!==undefined&&matchDraft?.[el.dataset.memberMinutes])matchDraft[el.dataset.memberMinutes].minutes=clamp(el.value,0,130)});
modalRoot.addEventListener('submit',async e=>{if(readOnly){e.preventDefault();return}if(e.target.id!=='modal-form')return;e.preventDefault();if(!currentModalSave)return;let btn=$('#modal-submit',modalRoot);if(btn){btn.disabled=true;btn.textContent='保存中…'}try{let success=await currentModalSave(e.target);if(success!==false){closeModal();render();toast('保存しました')}else if(btn){btn.disabled=false;btn.textContent='保存する'}}catch(err){console.error(err);toast('処理できませんでした');if(btn){btn.disabled=false;btn.textContent='保存する'}}});
root.addEventListener('pointerdown',e=>{if(readOnly)return;const b=e.target.closest('.pitch-player'),pitch=$('#pitch');if(!b||!pitch)return;drag={idx:n(b.dataset.slot),startX:e.clientX,startY:e.clientY,moved:false,ended:0,pointerId:e.pointerId};try{b.setPointerCapture(e.pointerId)}catch(_){} });
root.addEventListener('pointermove',e=>{if(readOnly)return;if(!drag||drag.pointerId!==e.pointerId)return;const b=$(`.pitch-player[data-slot="${drag.idx}"]`),pitch=$('#pitch');if(!b||!pitch)return;let dist=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY);if(dist>7)drag.moved=true;if(!drag.moved)return;const rect=pitch.getBoundingClientRect(),x=clamp((e.clientX-rect.left)/rect.width*100,5,95),y=clamp((e.clientY-rect.top)/rect.height*100,5,95);b.style.left=x+'%';b.style.top=y+'%';drag.x=x;drag.y=y;e.preventDefault();});
function dragEnd(e){if(!drag||drag.pointerId!==e.pointerId)return;if(drag.moved&&!readOnly){let slots=ensureSlots(c());slots[drag.idx].x=drag.x;slots[drag.idx].y=drag.y;saveSoon();drag.ended=Date.now();}else drag.ended=0;drag.pointerId=null;}
root.addEventListener('pointerup',dragEnd);root.addEventListener('pointercancel',dragEnd);
window.addEventListener('pagehide',()=>{if(app.careers.length)saveNow(false)});
if(cloud){
 document.addEventListener('careercloud:status',e=>{const el=$('#save-info');if(el)el.textContent=e.detail;const sync=$('#sync-state');if(sync)sync.textContent=e.detail});
 document.addEventListener('careercloud:remote-update',async e=>{if(!e.detail||!Array.isArray(e.detail.careers))return;app=e.detail;app.activeId=app.careers.find(x=>x.id===app.activeId)?.id||app.careers[0]?.id||null;activePage='home';subPage='';playerId=null;try{if(db)await dbPut(app,localKey)}catch(err){}render();toast('別端末の記録を反映しました')});
}

load();
})();
